1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
7	
8	/**
9	 * Consolidates all duplicate detection into a single derived {@code identityKey} (see
10	 * {@link IdentityKey}). Rejects a create-owner request with 409 via {@link DuplicateIdentityException}
11	 * only when the new owner's WHOLE identityKey equals an existing owner's identityKey; the separate
12	 * telephone, email and household duplicate checks are all expressed through this one key.
13	 *
14	 * <p>Because the telephone is part of the key, two members of the same household (same
15	 * {@code householdId}) with different telephones have different identityKeys and are both allowed;
16	 * only an exact full-key match is a duplicate. Runs after {@link AssignHousehold}, so the new owner's
17	 * householdId is finalized before its key is derived, and before {@link SaveOwner}.
18	 */
19	public class EnsureUniqueIdentity {
20	
21	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
22	            throws DuplicateIdentityException {
23	        String identityKey = IdentityKey.of(owner);
24	        for (Owner existing : ownerRepository.findAll()) {
25	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
26	                continue; // the owner being created is not yet its own duplicate
27	            }
28	            if (IdentityKey.of(existing).equals(identityKey)) {
29	                throw new DuplicateIdentityException(identityKey);
30	            }
31	        }
32	    }
33	}
