1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
5	
6	/**
7	 * Derives an owner's {@code identityKey}, the single value all duplicate detection is expressed
8	 * through:
9	 *
10	 * <pre>identityKey = normalizedTelephone + '|' + (email or empty) + '|' + householdId</pre>
11	 *
12	 * <p>The telephone is normalized to its E.164 form (see {@link E164Telephone}); a value that cannot
13	 * form a valid E.164 number is used verbatim so the key stays defined for every stored owner. The
14	 * email contributes its lower-cased form, or the empty string when absent. The householdId
15	 * contributes its stored value, or the empty string when the owner is not part of a household.
16	 *
17	 * <p>Two owners are duplicates only when their WHOLE identityKey is equal, so members of the same
18	 * household with different telephones have different keys and are both allowed.
19	 */
20	public final class IdentityKey {
21	
22	    private IdentityKey() {
23	    }
24	
25	    public static String of(Owner owner) {
26	        return normalizeTelephone(owner.getTelephone()) + "|" + normalizeEmail(owner.getEmail()) + "|"
27	                + (owner.getHouseholdId() == null ? "" : owner.getHouseholdId());
28	    }
29	
30	    private static String normalizeTelephone(String telephone) {
31	        try {
32	            return E164Telephone.normalize(telephone);
33	        }
34	        catch (InvalidTelephoneException ex) {
35	            return telephone == null ? "" : telephone;
36	        }
37	    }
38	
39	    private static String normalizeEmail(String email) {
40	        return email == null || email.isBlank() ? "" : email.toLowerCase();
41	    }
42	}
