5	import org.springframework.http.HttpStatus;
6	import org.springframework.http.ProblemDetail;
7	import org.springframework.http.ResponseEntity;
8	
9	/**
10	 * Responds 409 when a create-owner request derives an {@code identityKey} whose whole value is
11	 * already used by another owner. The body is a {@link ProblemDetail}.
12	 */
13	public class DuplicateIdentityExceptionHandler {
14	
15	    public void handle(@Parameter DuplicateIdentityException ex,
16	            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
17	        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.CONFLICT,
18	                "The identity key is already used by another owner");
19	        response.send(ResponseEntity.status(HttpStatus.CONFLICT).body(detail));
20	    }
21	}
