1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.regex.Pattern;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
8	
9	/**
10	 * Normalizes the optional {@code email} of an owner request. Email is optional: a null or blank
11	 * value is left untouched (no email). When present it must be a syntactically valid address,
12	 * otherwise the request is rejected with a 400 via {@link InvalidEmailException}. A valid address is
13	 * mutated in place (via {@code @Val}) to its lower-cased form, so the stored and returned
14	 * {@code email} is lower-case. Runs before {@link BuildOwner}/{@code ApplyOwner}.
15	 */
16	public class NormalizeOwnerEmail {
17	
18	    /** A pragmatic single-address check: local part, '@', domain with at least one dot, no spaces. */
19	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
20	
21	    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
22	        String email = request.getEmail();
23	        if (email == null || email.isBlank()) {
24	            return; // email is optional
25	        }
26	        String trimmed = email.trim();
27	        if (!EMAIL.matcher(trimmed).matches()) {
28	            throw new InvalidEmailException(email);
29	        }
30	        request.setEmail(trimmed.toLowerCase());
31	    }
32	}
