1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.mapper.CityRegion;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
7	
8	/**
9	 * Validates the owner's {@code postcode} WHEN PRESENT, so an owner created without a postcode stays
10	 * accepted (the request contract is backward-compatible). A supplied postcode must be exactly four
11	 * digits and, when the city has a known region, must fall within that region's fixed range
12	 * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region accepts any 4-digit
13	 * postcode. Anything else is rejected with 400 via {@link InvalidPostcodeException}.
14	 *
15	 * <p>Reads the body published by the preceding validate step via {@code @Val}, so it runs before the
16	 * owner is built/loaded and an invalid postcode is a 400 rather than being masked by a later step.
17	 */
18	public class ValidateOwnerPostcode {
19	
20	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
21	        String postcode = request.getPostcode();
22	        if (postcode == null || postcode.isBlank()) {
23	            return; // optional when absent
24	        }
25	        String city = request.getCity();
26	        if (!postcode.matches("[0-9]{4}")) {
27	            throw new InvalidPostcodeException(postcode, city, "must be exactly four digits");
28	        }
29	        int[] range = CityRegion.postcodeRange(city);
30	        if (range == null) {
31	            return; // no known region for this city; any 4-digit postcode is valid
32	        }
33	        int value = Integer.parseInt(postcode);
34	        if (value < range[0] || value > range[1]) {
35	            throw new InvalidPostcodeException(postcode, city,
36	                    "out of range " + range[0] + "-" + range[1] + " for the city's region");
37	        }
38	    }
39	}
